function reports(){
  const r=state.report,t=r.totals;
  const metrics=[['Unique participants',t.students,'Count each child once','students'],['Program enrollments',t.program_enrollments,'Distinct child–program pairs','students'],['Recorded visits',t.attended,`${t.attended-t.rate_attended} optional event check-ins included`,'attendance'],['Approved volunteer hours',t.approved_hours,`${t.pending_hours} hours pending review`,'hours'],['Paired self-assessments',t.assessment_pairs,`${t.assessment_missing_end} end assessments missing`,'pairs'],['Unfinished rosters',t.incomplete_sessions,`${t.unmarked} entries not recorded`,'incomplete']];
  shell(heading('A report you can trace.','Q3 2026 · July 1–September 30 · Provisional · Fictional demonstration',`${btn('Download evidence','download-report','download')}${btn('Print / save PDF','print','report')}`)+`<div class="callout"><div>${icon('info')}</div><div><strong>Provisional until outstanding records are reviewed.</strong><p>${t.incomplete_sessions} unfinished rosters, ${t.pending_hours} pending volunteer hours, and ${t.assessment_missing_end} missing end assessments. The scenario date is September 24; the quarter has not closed.</p></div></div><div class="report-grid">${metrics.map(([label,value,sub,kind])=>`<button class="report-metric" data-action="evidence" data-kind="${kind}"><span class="muted">${label}</span><strong class="number">${value}</strong><small>${sub} ${icon('arrow')}</small></button>`).join('')}</div>`+panel('Quarterly narrative','Computed figures come from the database. Draft wording requires staff review.',`<div class="panel-body"><div class="callout info"><div>${icon('spark')}</div><div><strong>${state.ai_available?'Workers AI is available':'Template drafting is available'}</strong><p>The assistant summarizes verified totals. It does not invent outcomes, send communications, or access counseling records.</p></div></div><div id="report-output" class="report-text">${reportDraft?E(reportDraft.text):'Generate a draft to turn this quarter’s verified figures and outstanding issues into a board-ready starting point.'}</div><p class="small muted" id="report-source" style="margin-top:16px">${reportDraft?E(reportDraft.source)+' · '+E(reportDraft.warning||'Review against the evidence before sharing.'):'No narrative generated yet.'}</p></div>`,btn('Draft quarterly narrative','draft-report','spark',true))+`<section class="panel" style="margin-top:24px"><header class="panel-head"><h2>Definitions behind the numbers</h2></header><div class="panel-body"><p><strong>Attendance:</strong> present and late entries divided by present, late, and unexplained absent entries from submitted regular-session rosters. Optional community events, excused absences, cancelled sessions, and unsubmitted attendance are excluded. Event check-ins remain in recorded-visit totals.</p><p style="margin-top:12px"><strong>Assessment change:</strong> ${t.average_gain.toFixed(2)} points on a five-point scale among paired responses. Fictional, descriptive program feedback; not a clinical assessment or proof of causality.</p><p style="margin-top:12px"><strong>Reporting scope:</strong> this ${t.students}-student demo is a subset of TidePath’s approximately 900 children served annually. Donor, grant accounting, and counseling records remain in their existing systems.</p></div></section>`,'reports');
}
function evidence(kind){
  const e=state.report.evidence;let title,headers,rows;
  if(kind==='students'){title='Unique participants · source records';headers=['Participant','Programs'];rows=e.students.map(s=>[name(s),s.programs]);}
  else if(kind==='attendance'){title='Submitted attendance · source records';headers=['Participant','Session','Date','Status'];rows=e.attendance.map(a=>[a.name,a.group_name,a.date,a.status]);}
  else if(kind==='hours'){title='Volunteer hours · source records';headers=['Volunteer','Session','Hours','Approval'];rows=e.hours.map(h=>[h.volunteer_name,`${h.date} · ${h.group_name}`,h.hours,h.status]);}
  else if(kind==='pairs'){title='Paired self-assessments · fictional';headers=['Student','Program','Start','End','Change'];rows=e.pairs.map(p=>[p.name,state.programs.find(pr=>pr.id===p.program_id)?.name,p.start,p.end,p.gain]);}
  else{title='Incomplete rosters';headers=['Session','Date','Not recorded'];rows=e.incomplete.map(s=>[s.group_name,s.date,s.unmarked]);}
  showDialog(title,`<p class="muted small">${rows.length} source records. These totals update when records change; this is not an immutable issued report.</p><div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${E(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);
}
